let orders=[],view='all',editing=null,dirty=false,busy=false,assignees=[],listSort={key:'markShipDate',dir:1},shipReview=false,shipPick=new Set();
async function api(path,data){const r=await fetch(path,data?{method:'POST',headers:{'Content-Type':'application/json','X-Desk-Request':'1'},body:JSON.stringify(data)}:{});const result=await r.json();if(!r.ok){if(r.status===401&&!['/api/login','/api/recover'].includes(path)&&typeof authScreen==='function'){currentUser=null;dirty=false;authScreen('login')}throw Error(result.error||'処理できませんでした。');}return result}
