function deskAdmin(){return !!currentUser&&currentUser.role!=='owner'&&(!!currentUser.manage||!!currentUser.overview)}
function paintAuthors(){const sel=$('#author');if(!sel)return;const show=seesAll();$('#authorfilter').hidden=!show;if(!show){sel.value='';return}const prev=sel.value;const people=[...new Map(orders.map(o=>chargeOf(o))).entries()];if(deskAdmin()&&!people.some(([id])=>id===String(currentUser.id)))people.push([String(currentUser.id),currentUser.name||'自分']);people.sort((a,b)=>a[1].localeCompare(b[1],'ja'));sel.innerHTML='<option value="">すべての担当</option>'+people.map(([id,name])=>`<option value="${esc(id)}">${esc(name)}</option>`).join('');if(!authorPinned&&deskAdmin()){authorPinned=true;if([...sel.options].some(o=>o.value===String(currentUser.id)))sel.value=String(currentUser.id);return}if([...sel.options].some(o=>o.value===prev))sel.value=prev}
function doneQuery(){return !!($('#search').value.trim()||$('#from').value||$('#to').value)}
function selected(){const q=$('#search').value.trim().toLowerCase(),status=$('#status').value,sort=$('#sort').value,from=$('#from').value,to=$('#to').value,author=$('#author')?.value||'';return orders.filter(o=>{if(view==='done'){if(o.status!=='完了'||!doneQuery())return false}else if(view==='shipped'){if(o.status!=='発送済'||!doneQuery())return false}else if((view==='all'||view==='floor')&&o.status==='完了')return false;if(view==='floor'&&o.status==='発送済')return false;if(view==='all'&&shipReview&&o.status!=='発送済')return false;if((view==='all'||view==='floor')&&o.status==='下書き')return false;if(view==='draft'&&o.status!=='下書き')return false;if(status&&o.status!==status)return false;if(view==='all'&&$('#dueneed')?.checked&&!dueNeedsConfirm(o))return false;if(author&&chargeOf(o)[0]!==author)return false;if(q&&![o.customer,o.employee,o.owner,o.number,o.authorName,o.assigneeName].some(x=>String(x||'').toLowerCase().includes(q)))return false;if(from&&!(o[sort]&&o[sort]>=from))return false;if(to&&!(o[sort]&&o[sort]<=to))return false;return true}).sort(compareOrders)}
function compareFloorOrders(a,b){
 const ad=String(a.markShipDate||''),bd=String(b.markShipDate||'');
 if(!ad&&bd)return 1;if(ad&&!bd)return -1;
 const dateOrder=ad.localeCompare(bd);if(dateOrder)return dateOrder;
 return String(a.number||'').localeCompare(String(b.number||''),'ja',{numeric:true})||a.id-b.id;
}
function compareOrders(a,b){if(view==='floor')return compareFloorOrders(a,b);const key=listSort.key,dir=listSort.dir;if(key==='status'){const cmp=states.indexOf(a.status)-states.indexOf(b.status);return cmp?cmp*dir:b.id-a.id}const av=String(a[key]??''),bv=String(b[key]??'');if(!av&&bv)return 1;if(av&&!bv)return -1;const cmp=av.localeCompare(bv,'ja',{numeric:true});return cmp?cmp*dir:b.id-a.id}
