function substituteMarkText(o){if(o.shipEstimateUnknown)return '未定';if(o.shipEstimateDate)return o.shipEstimateDate;return '未設定'}
function dueConfirmCompareText(o){const mark=o.markShipDate||'未設定';const sub=substituteMarkText(o);const late=!o.shipEstimateUnknown&&o.shipEstimateDate&&o.markShipDate&&o.shipEstimateDate>o.markShipDate;if(o.shipEstimateUnknown)return '営業指定のマーク出荷日 '+mark+' → 代わり 未定。';if(o.shipEstimateDate)return '営業指定のマーク出荷日 '+mark+' → 代わり '+sub+(late?'（指定超過）':'')+'。';return '営業指定のマーク出荷日 '+mark+'。代わりのマーク出荷日は未設定です。'}
function dueConfirmStateText(o){if(dueConfirmed(o))return '確認済み　'+(o.salesConfirmedBy||'')+'　'+(o.salesConfirmedAt||'').replace('T',' ')+(o.salesConfirmNote?'　'+o.salesConfirmNote:'');const compare=dueConfirmCompareText(o);if(dueNeedsConfirm(o))return compare+'顧客と調整したあと、確認済みにしてください。';return compare+'確認は不要です。在庫不足だけでは、マーク出荷日に間に合う場合は確認不要です。'}
function openDue(o,opts={}){dueOrder=o;$('#dueerror').textContent='';$('#duemessage').textContent='';$('#duenumber').textContent=o.number||'下書き';$('#duecustomer').textContent=o.customer||'';$('#dueemployee').textContent=o.employee||'—';$('#duestatus').textContent=o.status||'';$('#duemark').textContent=o.markShipDate||'未設定';const sub=$('#duesubstitute');if(sub)sub.textContent=substituteMarkText(o);$('#dueprogress').value=o.floorProgress||'通常作業';$('#duerequested').value=o.repairRequestedDate||'';$('#dueready').value=o.repairReadyDate||'';$('#dueunknown').checked=!!o.shipEstimateUnknown;$('#dueestimate').value=o.shipEstimateUnknown?'':(o.shipEstimateDate||'');$('#duenote').value=o.floorNote||'';$('#dueconfirmnote').value='';$('#dueupdated').textContent=o.floorUpdatedAt?('最終更新 '+(o.floorUpdatedAt||'').replace('T',' ')+'　'+(o.floorUpdatedBy||'')):'現場の進捗はまだ登録されていません。代わりのマーク出荷日が空でも、未定にはなりません。';const confirmOnly=!!opts.confirmOnly||!dueCanEdit();const edit=dueCanEdit()&&!confirmOnly;const title=$('#duetitle');if(title)title.textContent=confirmOnly?'納期を確認':'進捗・納期';$('#duefloor').hidden=confirmOnly;$('#duefloor').disabled=!edit;$('#duesave').hidden=!edit;paintShortages(o);paintShortageCompare(o,confirmOnly);const confirm=dueCanConfirm();$('#dueconfirmbox').hidden=!confirm;const need=dueNeedsConfirm(o);$('#dueconfirmbtn').hidden=!confirm||!need;$('#dueconfirmstate').textContent=dueConfirmStateText(o);syncDueUnknown();if(!$('#duedesk').open)$('#duedesk').showModal()}
function repairDelayDefaultProgress(o){const cur=o.floorProgress||'';if(cur==='修理待ち'||cur==='修理中'||cur==='修理完了')return cur;return '修理中'}
function delayKindOf(o){const repair=o.floorProgress&&o.floorProgress!=='通常作業';const shortage=Array.isArray(o.shortages)&&o.shortages.length;if(repair&&shortage)return 'both';if(shortage)return 'shortage';return 'repair'}
function selectedDelayKind(){return document.querySelector('input[name="delaykind"]:checked')?.value||'repair'}
function syncDelayKind(){const kind=selectedDelayKind();const repair=kind==='repair'||kind==='both';const shortage=kind==='shortage'||kind==='both';const r=$('#delayrepair');const s=$('#delayshortage');if(r)r.hidden=!repair;if(s)s.hidden=!shortage}
function syncDelayUnknown(){const on=$('#delayunknown')?.checked;const est=$('#delayestimate');if(!est)return;est.disabled=!!on;if(on)est.value=''}
function shortageQtyMap(o){const map=new Map();for(const s of (Array.isArray(o.shortages)?o.shortages:[])){if(s&&s.lineId)map.set(s.lineId,s)}return map}
function paintDelayShortages(o){const box=$('#delayshortagerows');if(!box)return;const items=Array.isArray(o.items)?o.items:[];const ids=dueLineIds(items);const by=shortageQtyMap(o);const named=items.map((it,i)=>({it,line:ids[i]})).filter(x=>String(x.it.name||'').trim());if(!named.length){box.innerHTML='<p class="duehint">商品名のある明細がありません。</p>';return}box.innerHTML=named.map(({it,line})=>{const prev=by.get(line);const ship=Math.max(0,Number(it.quantity)||0);let qty=prev?Number(prev.qty)||0:0;if(qty>ship)qty=ship;const on=qty>0?' shortageon':'';return `<div class="shortageqtyrow${on}" data-line="${esc(line)}" data-ship="${ship}"${prev?.id?` data-id="${esc(prev.id)}"`:''}><p>${esc(supplyLabel(it))}</p><label>出荷枚数<span class="shipqty">${ship||'—'}</span></label><label>不足枚数<input data-k="qty" type="number" min="0" max="${ship}" step="1" value="${qty}"></label></div>`}).join('');box.querySelectorAll('input[data-k="qty"]').forEach(el=>el.oninput=()=>{const row=el.closest('.shortageqtyrow');if(!row)return;const cap=Number(row.dataset.ship);if(Number.isFinite(cap)&&el.value!==''&&Number(el.value)>cap)el.value=String(cap);row.classList.toggle('shortageon',Number(el.value)>0)})}
function readDelayShortages(){return [...$('#delayshortagerows').querySelectorAll('.shortageqtyrow')].map(row=>{const qty=Number(row.querySelector('[data-k="qty"]')?.value);if(!Number.isInteger(qty)||qty<1)return null;const item={lineId:row.dataset.line,qty};if(row.dataset.id)item.id=row.dataset.id;return item}).filter(Boolean)}
function paintShortageCompare(o,force){const box=$('#dueshortagecompare');const rows=$('#dueshortagecomparerows');if(!box||!rows)return;const items=Array.isArray(o.items)?o.items:[];const ids=dueLineIds(items);const by=shortageQtyMap(o);const named=items.map((it,i)=>({it,line:ids[i]})).filter(x=>String(x.it.name||'').trim());const has=by.size>0;box.hidden=!(force||has);if(!named.length){rows.innerHTML='<p class="duehint">商品明細がありません。</p>';return}rows.innerHTML=named.map(({it,line})=>{const prev=by.get(line);const ship=Number(it.quantity)||0;const qty=prev?Number(prev.qty)||0:0;const on=qty>0?' shortageon':'';return `<div class="shortageqtyrow${on}"><p>${esc(supplyLabel(it))}</p><label>出荷枚数<span class="shipqty">${ship||'—'}</span></label><label>不足枚数<span class="shipqty">${qty||'なし'}</span></label></div>`}).join('')}
function openDelay(o){if(!dueCanEdit()){openDue(o);return}dueOrder=o;$('#delayerror').textContent='';$('#delaymessage').textContent='';$('#delaynumber').textContent=o.number||'下書き';$('#delaycustomer').textContent=o.customer||'';$('#delayemployee').textContent=o.employee||'—';$('#delaystatus').textContent=o.status||'';$('#delaymark').textContent=o.markShipDate||'未設定';const kind=delayKindOf(o);document.querySelectorAll('input[name="delaykind"]').forEach(el=>{el.checked=el.value===kind});$('#delayprogress').value=repairDelayDefaultProgress(o);$('#delayunknown').checked=!!o.shipEstimateUnknown;$('#delayestimate').value=o.shipEstimateUnknown?'':(o.shipEstimateDate||'');$('#delaynote').value=o.floorNote||'';$('#delayupdated').textContent=o.floorUpdatedAt?('最終更新 '+(o.floorUpdatedAt||'').replace('T',' ')+'　'+(o.floorUpdatedBy||'')):(o.markShipDate&&o.markShipDate<today()?'マーク出荷日を過ぎています。代わりの日や不足枚数を登録してください。':'代わりのマーク出荷日が空でも、未定にはなりません。');paintDelayShortages(o);syncDelayKind();syncDelayUnknown();$('#delaysave').hidden=false;if($('#duedesk').open)$('#duedesk').close();if(!$('#delaydesk').open)$('#delaydesk').showModal()}
function replaceDue(saved){const i=orders.findIndex(x=>x.id===saved.id);if(i>=0)orders[i]=saved;else orders.unshift(saved);dueOrder=saved;render()}
