$('#dueaddsupply').onclick=()=>{if(!dueCanEdit()||!dueOrder)return;$('#dueerror').textContent='';const items=Array.isArray(dueOrder.items)?dueOrder.items:[];const ids=dueLineIds(items);const used=new Set([...$('#duesupplyrows').querySelectorAll('.supplyrow')].map(r=>r.dataset.line));const choices=items.map((it,i)=>({line:ids[i],label:supplyLabel(it)})).filter((c,i)=>String(items[i].name||'').trim()&&!used.has(c.line));if(!choices.length){$('#dueerror').textContent=items.some(it=>String(it.name||'').trim())?'同じ商品の不足は1件にまとめてください。':'商品名のある明細がありません。';return}const empty=$('#supplyempty');if(empty)empty.remove();const row=document.createElement('div');row.className='supplyrow';row.dataset.line=choices[0].line;row.innerHTML=`<label>対象商品<select data-k="line">${choices.map(c=>`<option value="${esc(c.line)}">${esc(c.label)}</option>`).join('')}</select></label>${supplyFields({})}`;$('#duesupplyrows').append(row);bindSupplyRow(row)};
$('#dueform').onsubmit=async e=>{e.preventDefault();if(busy||!dueOrder||!dueCanEdit())return;busy=true;$('#dueerror').textContent='';$('#duemessage').textContent='';$('#duesave').disabled=true;const shortages=readShortages();const review=supplyDateChanged(dueOrder.shortages,shortages);try{const saved=await api('/api/orders/floor-progress',{id:dueOrder.id,version:dueOrder.version,floorProgress:$('#dueprogress').value,repairRequestedDate:$('#duerequested').value,repairReadyDate:$('#dueready').value,shipEstimateDate:$('#dueunknown').checked?'':$('#dueestimate').value,shipEstimateUnknown:$('#dueunknown').checked,floorNote:$('#duenote').value,shortages});replaceDue(saved);if(review){openDue(saved);$('#duemessage').textContent='メーカー出荷予定日または入荷予定日が変わりました。代わりのマーク出荷日を見直してください。自動では変わりません。';toast('現場の進捗を保存しました。代わりのマーク出荷日を確認してください。')}else{$('#duedesk').close();toast('現場の進捗を保存しました。')}}catch(err){$('#dueerror').textContent=err.message}finally{busy=false;$('#duesave').disabled=false}};
$('#delayform').onsubmit=async e=>{e.preventDefault();if(busy||!dueOrder||!dueCanEdit())return;const kind=selectedDelayKind();const wantRepair=kind==='repair'||kind==='both';const wantShortage=kind==='shortage'||kind==='both';if(wantShortage){const over=[...$('#delayshortagerows').querySelectorAll('.shortageqtyrow')].find(row=>{const el=row.querySelector('[data-k="qty"]');const v=el?.value;if(v===''||v==null)return false;const n=Number(v);const cap=Number(row.dataset.ship);return Number.isInteger(n)&&n>=0&&Number.isFinite(cap)&&n>cap});if(over){$('#delayerror').textContent='不足枚数は出荷枚数を超えられません。';return}const bad=[...$('#delayshortagerows').querySelectorAll('[data-k="qty"]')].find(el=>{const v=el.value;if(v===''||v==null)return true;const n=Number(v);return !Number.isInteger(n)||n<0});if(bad){$('#delayerror').textContent='不足枚数は0以上の整数で入力してください。';return}}busy=true;$('#delayerror').textContent='';$('#delaymessage').textContent='';$('#delaysave').disabled=true;try{const body={id:dueOrder.id,version:dueOrder.version};if(wantRepair){body.floorProgress=$('#delayprogress').value;body.repairRequestedDate=dueOrder.repairRequestedDate||'';body.repairReadyDate=dueOrder.repairReadyDate||'';body.shipEstimateDate=$('#delayunknown').checked?'':$('#delayestimate').value;body.shipEstimateUnknown=$('#delayunknown').checked;body.floorNote=$('#delaynote').value}else{body.floorProgress=dueOrder.floorProgress||'通常作業';body.repairRequestedDate=dueOrder.repairRequestedDate||'';body.repairReadyDate=dueOrder.repairReadyDate||'';body.shipEstimateDate=dueOrder.shipEstimateUnknown?'':(dueOrder.shipEstimateDate||'');body.shipEstimateUnknown=!!dueOrder.shipEstimateUnknown;body.floorNote=dueOrder.floorNote||''}if(wantShortage)body.shortages=readDelayShortages();const saved=await api('/api/orders/floor-progress',body);replaceDue(saved);$('#delaydesk').close();toast(kind==='shortage'?'在庫不足を保存しました。':kind==='both'?'修理と在庫不足の遅延を保存しました。':'修理遅延を保存しました。')}catch(err){$('#delayerror').textContent=err.message}finally{busy=false;$('#delaysave').disabled=false}};
$('#dueconfirmbtn').onclick=async()=>{if(busy||!dueOrder||!dueCanConfirm())return;busy=true;$('#dueerror').textContent='';$('#duemessage').textContent='';$('#dueconfirmbtn').disabled=true;try{const saved=await api('/api/orders/due-confirm',{id:dueOrder.id,version:dueOrder.version,salesConfirmNote:$('#dueconfirmnote').value});replaceDue(saved);$('#duedesk').close();toast('納期を確認済みにしました。')}catch(err){$('#dueerror').textContent=err.message}finally{busy=false;$('#dueconfirmbtn').disabled=false}};
