const debugMethods=['車両便','送り','オリコン','担当者へ','その他'];
function debugStamp(v){return v?String(v).slice(0,16):''}
function debugPersonOptions(list,selected){return '<option value="">記録なし</option>'+list.map(w=>`<option value="${w.id}"${String(selected||'')===String(w.id)?' selected':''}>${esc(w.name)}</option>`).join('')}
function debugNote(tr){const note=tr.querySelector('[data-k="shipMethodNote"]');if(note)note.hidden=tr.querySelector('[data-k="shipMethod"]').value!=='その他'}
function debugRead(tr){const val=k=>tr.querySelector(`[data-k="${k}"]`).value;const num=k=>{const v=val(k);return v?Number(v):null};const at=k=>{const v=val(k);return v?v+':00':''};return {id:Number(tr.dataset.id),version:Number(tr.dataset.version),status:val('status'),printed:tr.querySelector('[data-k="printed"]').checked,shipMethod:val('shipMethod'),shipMethodNote:val('shipMethod')==='その他'?val('shipMethodNote').trim():'',shipWorkerId:num('shipWorkerId'),shippedAt:at('shippedAt'),barcodeScanById:num('barcodeScanById'),barcodeScanAt:at('barcodeScanAt')}}
function paintDebugDesk(workers){let box=$('#debugdeskdialog');if(!box){box=document.createElement('dialog');box.id='debugdeskdialog';document.body.append(box)}const list=[...orders].sort((a,b)=>b.id-a.id);const statusKeep=states.map(s=>'<option>'+s+'</option>').join('');const methodKeep=debugMethods.map(m=>'<option>'+m+'</option>').join('');const workerKeep=workers.map(w=>'<option value="'+w.id+'">'+esc(w.name)+'</option>').join('');const rows=list.map(o=>'<tr data-id="'+o.id+'" data-version="'+o.version+'"><td><input type="checkbox" class="debugpick" aria-label="選ぶ"></td><td>'+(esc(o.number)||'—')+'</td><td>'+esc(o.customer)+'<small>'+(esc(o.employee)||'')+'</small></td><td><select data-k="status">'+states.map(s=>'<option'+(s===o.status?' selected':'')+'>'+s+'</option>').join('')+'</select></td><td><input data-k="printed" type="checkbox" '+(o.printedAt?'checked':'')+' aria-label="印刷済"></td><td><select data-k="barcodeScanById">'+debugPersonOptions(workers,o.barcodeScanById)+'</select></td><td><input data-k="barcodeScanAt" type="datetime-local" value="'+esc(debugStamp(o.barcodeScanAt))+'"></td><td><select data-k="shipWorkerId">'+debugPersonOptions(workers,o.shipWorkerId)+'</select></td><td><select data-k="shipMethod"><option value="">記録なし</option>'+debugMethods.map(m=>'<option'+(m===(o.shipMethod||'')?' selected':'')+'>'+m+'</option>').join('')+'</select></td><td><input data-k="shipMethodNote" value="'+esc(o.shipMethodNote||'')+'" maxlength="40"'+(o.shipMethod==='その他'?'':' hidden')+'></td><td><input data-k="shippedAt" type="datetime-local" value="'+esc(debugStamp(o.shippedAt))+'"></td></tr>').join('')||'<tr><td colspan="11">指示書はありません。</td></tr>';box.innerHTML='<div class="dialoghead"><div><h2>指示書の状態・記録を修正</h2><p>主管理者専用。状況、印刷、出荷仕分けの記録をまとめて変更します。</p></div><button type="button" class="quiet" id="debugclose">閉じる ×</button></div><div class="dialogbody"><div class="debugtools"><label>絞り込み<input id="debugq" placeholder="指示番号・顧客・従業員"></label><label>状況<select id="debugbulkstatus"><option value="">変更しない</option>'+statusKeep+'</select></label><label>印刷<select id="debugbulkprint"><option value="">変更しない</option><option value="1">印刷済</option><option value="0">未印刷</option></select></label><label>出荷方法<select id="debugbulkmethod"><option value="">変更しない</option><option value="-">記録なし</option>'+methodKeep+'</select></label><label>作業者<select id="debugbulkworker"><option value="">変更しない</option><option value="-">記録なし</option>'+workerKeep+'</select></label><button type="button" id="debugapply">選択行に反映</button><button type="button" class="primary" id="debugsave">変更を保存</button></div><p id="debugerror" role="alert"></p><div class="tablewrap"><table><thead><tr><th><input type="checkbox" id="debugall" aria-label="すべて選ぶ"></th><th>指示番号</th><th>顧客 / 従業員</th><th>状況</th><th>印刷</th><th>バーコード</th><th>発行日時</th><th>発送者</th><th>出荷方法</th><th>その他</th><th>発送日時</th></tr></thead><tbody id="debugrows">'+rows+'</tbody></table></div></div>';list.forEach(o=>{const tr=box.querySelector('tr[data-id="'+o.id+'"]');if(tr)tr.dataset.origin=JSON.stringify(debugRead(tr))});box.querySelectorAll('#debugrows tr[data-id]').forEach(debugNote);box.querySelectorAll('[data-k="shipMethod"]').forEach(el=>el.addEventListener('change',()=>debugNote(el.closest('tr'))));const filter=()=>{const q=$('#debugq').value.trim().toLowerCase();box.querySelectorAll('#debugrows tr[data-id]').forEach(tr=>{tr.hidden=q&&!tr.innerText.toLowerCase().includes(q)})};$('#debugq').oninput=filter;$('#debugall').onchange=e=>{box.querySelectorAll('#debugrows tr[data-id]:not([hidden]) .debugpick').forEach(el=>{el.checked=e.target.checked})};$('#debugapply').onclick=()=>{const status=$('#debugbulkstatus').value,printed=$('#debugbulkprint').value,method=$('#debugbulkmethod').value,worker=$('#debugbulkworker').value;box.querySelectorAll('#debugrows tr[data-id]').forEach(tr=>{if(tr.hidden||!tr.querySelector('.debugpick').checked)return;if(status)tr.querySelector('[data-k="status"]').value=status;if(printed)tr.querySelector('[data-k="printed"]').checked=printed==='1';if(method)tr.querySelector('[data-k="shipMethod"]').value=method==='-'?'':method;if(worker)tr.querySelector('[data-k="shipWorkerId"]').value=worker==='-'?'':worker;debugNote(tr)})};$('#debugsave').onclick=async()=>{const changed=[];for(const tr of box.querySelectorAll('#debugrows tr[data-id]')){const now=debugRead(tr);if(JSON.stringify(now)!==tr.dataset.origin)changed.push(now)}$('#debugerror').textContent='';if(!changed.length){$('#debugerror').textContent='変更はありません。';return}if(changed.length>40){$('#debugerror').textContent='一度に保存できるのは40件までです。絞って分けてください。';return}if(!confirm(changed.length+'件の状態・記録の変更を保存しますか？'))return;$('#debugsave').disabled=true;try{const r=await api('/api/orders/debug',{items:changed});for(const o of r.orders){const i=orders.findIndex(x=>x.id===o.id);if(i>=0)orders[i]=o}paintDebugDesk(workers);render();toast(r.orders.length+'件を保存しました。')}catch(e){$('#debugerror').textContent=e.message;$('#debugsave').disabled=false}};$('#debugclose').onclick=()=>box.close();if(!box.open)box.showModal()}
async function openDebugDesk(){if(currentUser?.role!=='owner')return;try{paintDebugDesk(await api('/api/ship-workers'))}catch(e){toast(e.message)}}


if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'list_visible_instructions',title:'表示中の指示書を確認',description:'現在の一覧の検索条件に一致する指示書を読み取ります。変更はしません。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async(input)=>{if(!input||Object.keys(input).length)throw Error('入力項目はありません。');return selected().map(({number,customer,status,markShipDate,delivery})=>({number,customer,status,markShipDate,delivery}))}})).catch(()=>{})}catch{}}
